CREATE TABLE IF NOT EXISTS subscription_plans (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, price INTEGER NOT NULL, currency TEXT DEFAULT 'CNY', billing_cycle TEXT NOT NULL, credit_limit INTEGER NOT NULL, feature_config TEXT DEFAULT '{}', status TEXT DEFAULT 'active' CHECK (status IN ('active','inactive','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_subscription_plans_name ON subscription_plans(name); CREATE INDEX IF NOT EXISTS idx_subscription_plans_status ON subscription_plans(status); CREATE TABLE IF NOT EXISTS usage_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, service_type TEXT NOT NULL, resource_type TEXT, amount INTEGER NOT NULL, metadata TEXT DEFAULT '{}', created_at TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_usage_records_user_id ON usage_records(user_id); CREATE INDEX IF NOT EXISTS idx_usage_records_service_type ON usage_records(service_type); CREATE INDEX IF NOT EXISTS idx_usage_records_created_at ON usage_records(created_at);
